import scipy.io, numpy as np

# Check JEB6 with scipy
try:
    d = scipy.io.loadmat('/app/data/Ephys_Behavior/data_structure_JEB6_2021-04-18.mat', simplify_cells=True)
    obj = d['obj']
    print('JEB6 keys:', list(obj.keys()) if isinstance(obj, dict) else obj.dtype.names)
    aw = np.array(obj['bp']['autowater']).flatten()
    print(f'  trials={len(aw)}, WC={np.sum(aw==1)}, DR={np.sum(aw==0)}')
    clu = obj.get('clu', None)
    if clu is not None:
        print('  clu type:', type(clu))
        if isinstance(clu, np.ndarray):
            print('  clu shape:', clu.shape)
            for i, c in enumerate(clu.flatten()):
                if isinstance(c, dict):
                    print(f'  probe {i}: keys={list(c.keys())}, n_neurons={len(c[\"quality\"])}')
        elif isinstance(clu, dict):
            print('  clu keys:', list(clu.keys()))
            q = clu['quality']
            print(f'  n_neurons={len(q)}')
except Exception as e:
    print(f'JEB6 scipy error: {e}')

# Also check scipy JEB23 files
for fn in ['data_structure_JEB23_2023-10-18.mat', 'data_structure_JEB23_2023-10-20.mat', 'data_structure_JEB23_2023-10-21.mat']:
    try:
        d = scipy.io.loadmat(f'/app/data/RandomizedDelay_Ephys_Behavior/{fn}', simplify_cells=True)
        obj = d['obj']
        keys = list(obj.keys()) if isinstance(obj, dict) else list(obj.dtype.names)
        has_clu = 'clu' in keys
        print(f'{fn}: keys={keys}, has_clu={has_clu}')
        if has_clu:
            clu = obj['clu']
            print(f'  clu type: {type(clu)}')
            if isinstance(clu, np.ndarray):
                print(f'  clu shape: {clu.shape}')
                for i, c in enumerate(clu.flatten()[:3]):
                    if isinstance(c, dict):
                        print(f'  probe {i}: keys={list(c.keys())[:5]}, n_neurons={len(c.get(\"quality\",[]))}')
            elif isinstance(clu, dict):
                print(f'  n_neurons={len(clu.get(\"quality\",[]))}')
    except Exception as e:
        print(f'{fn}: error {e}')
" 2>&1

