function [xpos, ypos] = findPosition(taxis, obj, nTrials, view, feat, alignEv)

traj = obj.traj{view};

featix = findDLCFeatIndex(obj.traj,view,{feat});

xpos = nan(numel(taxis),nTrials);
ypos = nan(numel(taxis),nTrials);

vidshift = findVideoOffset(obj);
% vidshift = 1;

for i = 1:nTrials % for each trial

    trix = i;

    % check if video data for trial is good, skip if not
    if isfield(traj(trix),'NdroppedFrames')
        if isnan(traj(trix).NdroppedFrames )
            continue;
        end
    end

    % check if frameTimes exists, if not, create it
    if ~isfield(traj(trix),'frameTimes')
        traj(trix).frameTimes = (1:size(traj(trix).ts,1)) ./ 400;
    end

    % get feat trajs for valid trials
    if ~isnan(traj(trix).frameTimes)
        ts = traj(trix).ts(:,1:2,featix);
        % if tongue, don't smooth
        if ~contains(feat,'tongue')
            ts = mySmooth(ts, 1, 'reflect');
        end
        % linear interpolation of frameTimes to taxis
        tsinterp = interp1(traj(trix).frameTimes-vidshift-obj.bp.ev.(alignEv)(trix), ts, taxis);
    end

    xpos(:,i) = tsinterp(:,1);
    ypos(:,i) = tsinterp(:,2);



    % fill missing values for all features except tongue
    if ~contains(feat,'tongue')
        xpos(:,i) = fillmissing(xpos(:,i),'nearest');
        ypos(:,i) = fillmissing(ypos(:,i),'nearest');
    end

end


end  % findPosition

function [xpos, ypos] = findPosition(taxis, obj, nTrials, view, feat, alignEv)

traj = obj.traj{view};

featix = findDLCFeatIndex(obj.traj,view,{feat});

xpos = nan(numel(taxis),nTrials);
ypos = nan(numel(taxis),nTrials);

vidshift = findVideoOffset(obj);
% vidshift = 1;

for i = 1:nTrials % for each trial

    trix = i;

    % check if video data for trial is good, skip if not
    if isfield(traj(trix),'NdroppedFrames')
        if isnan(traj(trix).NdroppedFrames )
            continue;
        end
    end

    % check if frameTimes exists, if not, create it
    if ~isfield(traj(trix),'frameTimes')
        traj(trix).frameTimes = (1:size(traj(trix).ts,1)) ./ 400;
    end

    % get feat trajs for valid trials
    if ~isnan(traj(trix).frameTimes)
        ts = traj(trix).ts(:,1:2,featix);
        % if tongue, don't smooth
        if ~contains(feat,'tongue')
            ts = mySmooth(ts, 1, 'reflect');
        end
        % linear interpolation of frameTimes to taxis
        tsinterp = interp1(traj(trix).frameTimes-vidshift-obj.bp.ev.(alignEv)(trix), ts, taxis);
    end

    xpos(:,i) = tsinterp(:,1);
    ypos(:,i) = tsinterp(:,2);



    % fill missing values for all features except tongue
    if ~contains(feat,'tongue')
        xpos(:,i) = fillmissing(xpos(:,i),'nearest');
        ypos(:,i) = fillmissing(ypos(:,i),'nearest');
    end

end


end  % findPosition

function featix = findDLCFeatIndex(traj,view,featName)
% traj is obj.traj
% view is 1 or 2, for side or bottom cam  respectively
% featName is a 1x1 cell containing string of feature name

% returns the index of obj.traj{view}(trialix).featNames that corresponds
% to featName input argument

% find first trial without dummy data
for i = 1:numel(traj{view})
    feats = traj{view}(i).featNames;
    [~,mask] = patternMatchCellArray(feats,featName,'all');
    if any(mask)
        break
    end
end
trix = i;

[~,mask] = patternMatchCellArray(traj{view}(trix).featNames,featName,'all'); % use trial trix's featNames field to find index, should be same for all trials
featix = find(mask);

if isempty(featix)
    error(['Could not find index for feature: ' featName{1}]);
end

if numel(featix) > 1
    fns = traj{view}(trix).featNames;
    keep = false(size(featix));
    for i = 1:numel(featix)
        if strcmpi(featName,fns{featix(i)})
            keep(i) = true;
        end
    end
    featix = featix(keep);
end



end % findDLCFeatIndex

