1→function [out,kernsd] = mySmooth(x, N, varargin)
     2→% operates on first dimension only - make sure first dim is time
     3→% gaussian kernel with window size N
     4→% varargin:
     5→%   'reflect' - reflect N elements from beginning of time series across
     6→%               0 index
     7→%   'zeropad' - pad N zeros across 0 index
     8→%   'none'    - don't handle boundary conditions
     9→
    10→% returns:
    11→% - out: filtered data, same size as x
    12→% - kernsd: std dev of gaussian kernel
    13→
    14→% % example usage:
    15→% x = 5*sin(1:0.01:100)';
    16→% y = x + randn(size(x));
    17→% N = 51;
    18→% out = mySmooth(y,N,'reflect');
    19→% 
    20→% figure;
    21→% subplot(3,1,1); plot(x);
    22→% xlim([-100 200])
    23→% subplot(3,1,2); plot(y)
    24→% xlim([-100 200])
    25→% subplot(3,1,3); plot(out); %hold on; plot(out,'.','MarkerSize',6)
    26→% xlim([-100 200])
    27→
    28→
    29→%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    30→
    31→if N == 0 || N == 1 % no smoothing
    32→    out = x;
    33→    kernsd = 0;
    34→    return
    35→end
    36→
    37→if isrow(x) % if 1-d time series, ensure column vector
    38→    x = x';
    39→end
    40→
    41→if nargin > 2
    42→    % handle a boundary condition
    43→    bctype = varargin{1};
    44→    if strcmpi(bctype,'reflect')
    45→        x_filt = cat(1,x(1:N,:),x);
    46→        trim = N + 1;
    47→    elseif strcmpi(bctype,'zeropad')
    48→        x_filt = cat(1,zeros(N,size(x,2)),x);
    49→        trim = N + 1;
    50→    elseif strcmpi(bctype,'none')
    51→        x_filt = x;
    52→        trim = 1;
    53→    else
    54→        warning('invalid boundary condition type - regular smoothing');
    55→        x_filt = x;
    56→        trim = 1;
    57→    end
    58→else
    59→    % no bc handling
    60→    x_filt = x;
    61→    trim = 1;
    62→end
    63→
    64→
    65→
    66→Ncol = size(x_filt, 2);
    67→Nel = size(x_filt, 1);
    68→
    69→kern = gausswin(N);
    70→kernsd = std(1:N);
    71→
    72→
    73→kern(1:floor(numel(kern)/2)) = 0; %causal
    74→kern = kern./sum(kern);
    75→
    76→out = zeros(Nel, Ncol);
    77→for j = 1:Ncol
    78→    out(:, j) = conv(x_filt(:, j), kern, 'same');
    79→end
    80→out = out(trim:end,:);
