def load_session_scipy(fpath):
    """Load session data from older MATLAB format file."""
    d = scipy.io.loadmat(fpath, simplify_cells=True)
    obj = d['obj']
    bp = obj['bp']

    session = {}
    n_trials = int(np.array(bp['Ntrials']).flatten()[0])
    session['Ntrials'] = n_trials
    session['hit'] = np.array(bp['hit']).flatten().astype(bool)
    session['miss'] = np.array(bp['miss']).flatten().astype(bool)
    session['no'] = np.array(bp['no']).flatten().astype(bool)
    session['early'] = np.array(bp['early']).flatten().astype(bool)
    session['autowater'] = np.array(bp['autowater']).flatten().astype(int)
    session['L'] = np.array(bp['L']).flatten().astype(bool)
    session['R'] = np.array(bp['R']).flatten().astype(bool)
    session['stim_enable'] = np.array(bp['stim']['enable']).flatten().astype(bool)

    ev = bp['ev']
    session['goCue'] = np.array(ev['goCue']).flatten()
    session['sample'] = np.array(ev['sample']).flatten()
    session['delay'] = np.array(ev['delay']).flatten()

    # Lick times
    session['lickL'] = []
    session['lickR'] = []
    lickL = ev.get('lickL', None)
    lickR = ev.get('lickR', None)

    if lickL is not None:
        if isinstance(lickL, np.ndarray):
            for t in range(n_trials):
                try:
                    licks = np.array(lickL[t]).flatten() if lickL[t] is not None else np.array([])
                    session['lickL'].append(licks[~np.isnan(licks)] if len(licks) > 0 else np.array([]))
                except:
                    session['lickL'].append(np.array([]))
        else:
            session['lickL'] = [np.array([])] * n_trials
    else:
        session['lickL'] = [np.array([])] * n_trials

    if lickR is not None:
        if isinstance(lickR, np.ndarray):
            for t in range(n_trials):
                try:
                    licks = np.array(lickR[t]).flatten() if lickR[t] is not None else np.array([])
                    session['lickR'].append(licks[~np.isnan(licks)] if len(licks) > 0 else np.array([]))
                except:
                    session['lickR'].append(np.array([]))
        else:
            session['lickR'] = [np.array([])] * n_trials
    else:
        session['lickR'] = [np.array([])] * n_trials

    # Neural data
    clu = obj.get('clu', None)
    neurons = []
    if clu is not None and isinstance(clu, list):
        for neuron_dict in clu:
            if not isinstance(neuron_dict, dict):
                continue
            quality = str(neuron_dict.get('quality', '')).strip().lower()
            if quality in EXCLUDE_QUALITY:
                continue

            trialtm = np.array(neuron_dict['trialtm']).flatten()
            trial = np.array(neuron_dict['trial']).flatten().astype(int)

            neurons.append({
                'quality': quality,
                'trialtm': trialtm,
                'trial': trial,
            })
    session['neurons'] = neurons

    # Video tracking
    traj = obj.get('traj', None)
    if traj is not None:
        session['traj'] = []
        if isinstance(traj, list):
            for cam_data_raw in traj:
                if isinstance(cam_data_raw, dict):
                    cam_out = {'ts': [], 'frameTimes': [], 'featNames': []}
                    # Feature names
                    feat_names = cam_data_raw.get('featNames', [])
                    if isinstance(feat_names, np.ndarray):
                        feat_names = feat_names.flatten().tolist()
                    if isinstance(feat_names, list) and len(feat_names) > 0:
                        if isinstance(feat_names[0], np.ndarray):
                            feat_names = [str(fn.flatten()[0]) if fn.size > 0 else '' for fn in feat_names]
                        else:
                            feat_names = [str(fn) for fn in feat_names]
                    cam_out['featNames'] = feat_names

                    # ts and frameTimes per trial
                    ts_list = cam_data_raw.get('ts', [])
                    ft_list = cam_data_raw.get('frameTimes', [])
                    if isinstance(ts_list, np.ndarray):
                        ts_list = ts_list.flatten().tolist()
                    if isinstance(ft_list, np.ndarray):
                        ft_list = ft_list.flatten().tolist()

                    for t in range(n_trials):
                        try:
                            ts = ts_list[t] if t < len(ts_list) else None
                            if isinstance(ts, np.ndarray) and ts.ndim == 3:
                                # MATLAB: (nFrames, 3, nFeatures) -> need (nFeatures, 3, nFrames) for consistency
                                ts = ts.transpose(2, 1, 0)
                            cam_out['ts'].append(ts)
                        except:
                            cam_out['ts'].append(None)
                        try:
                            ft = ft_list[t] if t < len(ft_list) else None
                            if ft is not None:
                                ft = np.array(ft).flatten()
                            cam_out['frameTimes'].append(ft)
                        except:
                            cam_out['frameTimes'].append(None)

                    session['traj'].append(cam_out)
                elif isinstance(cam_data_raw, np.ndarray) and cam_data_raw.dtype.names is not None:
                    # Structured array - per trial
                    cam_out = {'ts': [], 'frameTimes': [], 'featNames': []}
                    for t in range(min(n_trials, len(cam_data_raw))):
                        trial_data = cam_data_raw[t]
                        if t == 0:
                            feat_names = trial_data['featNames']
                            if isinstance(feat_names, np.ndarray):
                                feat_names = feat_names.flatten().tolist()
                            cam_out['featNames'] = [str(fn) for fn in feat_names]

                        ts = trial_data.get('ts', None)
                        ft = trial_data.get('frameTimes', None)
                        if isinstance(ts, np.ndarray) and ts.ndim == 3:
                            ts = ts.transpose(2, 1, 0)
                        cam_out['ts'].append(ts)
                        cam_out['frameTimes'].append(np.array(ft).flatten() if ft is not None else None)

                    session['traj'].append(cam_out)
        elif isinstance(traj, np.ndarray):
            # Handle as array of camera data
            session['traj'] = []

    # Video offset
    try:
        sglx = obj['sglx']
        bp_bitstart = np.array(ev['bitStart']).flatten()
        sglx_bitstart = np.array(sglx['bitcode']['bitstart']).flatten()
        sglx_fs = float(np.array(sglx['fs']).flatten()[0])
        mode_bp = scipy_stats.mode(bp_bitstart[~np.isnan(bp_bitstart)], keepdims=False).mode
        mode_sglx = scipy_stats.mode(sglx_bitstart[~np.isnan(sglx_bitstart)], keepdims=False).mode
        session['vidshift'] = mode_sglx / sglx_fs - mode_bp
    except:
        session['vidshift'] = 0.5

    # Motion energy (embedded)
    me = obj.get('me', None)
    if me is not None:
        me_data = []
        if isinstance(me, np.ndarray):
            for t in range(n_trials):
                try:
                    me_trial = np.array(me[t]).flatten() if t < len(me) else None
                    me_data.append(me_trial)
                except:
                    me_data.append(None)
        elif isinstance(me, list):
            for t in range(n_trials):
                try:
                    me_trial = np.array(me[t]).flatten() if t < len(me) else None
                    me_data.append(me_trial)
                except:
                    me_data.append(None)
        session['me_embedded'] = me_data

    return session

